  "facts": [
    {
      "fact_text": {
        "text": "By default, Java interprets integer literals without a suffix as type int.",
        "refs": ["Q0000"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "By default, Java interprets decimal literals without a suffix as type double.",
